def skill():
    m, w = 1, 4
    a1 = Fraction(m**3, 6)
    a2 = Fraction(w**3 - m**3, 3) - Fraction(m*(w**2 - m**2), 2)
    return int(6*(a1 + a2))

def standard():
    x = Symbol('x')
    h = expand(x*(x - 1))
    pts = [Integer(0)] + sorted(set(r for r in solve(h, x) if r.is_real and 0 < r < 4)) + [Integer(4)]
    tot = 0
    for p_, q_ in zip(pts, pts[1:]):
        tot += Abs(integrate(h, (x, p_, q_)))
    tot = tot*Rational(6, 1)
    return int(tot)

def unique():
    return [standard()]
